/**
 * React 18 Core Hooks & Virtual DOM Engine (Air-Gapped Intranet Distribution)
 * Provides standard React.useState, React.useEffect, React.useMemo, React.useCallback,
 * React.useRef, and React.createElement with zero external network dependencies.
 */
(function (global) {
  let currentComponent = null;
  let hookIndex = 0;
  let rootInstance = null;

  function createElement(type, props, ...children) {
    props = props || {};
    const flatChildren = children.flat().filter(c => c !== null && c !== undefined && c !== false);
    return {
      type,
      props: {
        ...props,
        children: flatChildren.length === 1 ? flatChildren[0] : flatChildren
      }
    };
  }

  function useState(initialValue) {
    if (!currentComponent) throw new Error('useState called outside component');
    const comp = currentComponent;
    const index = hookIndex++;

    if (comp.hooks[index] === undefined) {
      comp.hooks[index] = typeof initialValue === 'function' ? initialValue() : initialValue;
    }

    const setState = (newValue) => {
      const resolved = typeof newValue === 'function' ? newValue(comp.hooks[index]) : newValue;
      if (comp.hooks[index] !== resolved) {
        comp.hooks[index] = resolved;
        scheduleRender();
      }
    };

    return [comp.hooks[index], setState];
  }

  function useEffect(callback, deps) {
    if (!currentComponent) throw new Error('useEffect called outside component');
    const comp = currentComponent;
    const index = hookIndex++;

    const oldHook = comp.hooks[index];
    const hasChanged = !oldHook || !deps || deps.some((dep, i) => !Object.is(dep, oldHook.deps[i]));

    if (hasChanged) {
      if (oldHook && typeof oldHook.cleanup === 'function') {
        oldHook.cleanup();
      }
      comp.pendingEffects.push(() => {
        const cleanup = callback();
        comp.hooks[index] = { deps, cleanup };
      });
    }
  }

  function useMemo(factory, deps) {
    if (!currentComponent) throw new Error('useMemo called outside component');
    const comp = currentComponent;
    const index = hookIndex++;

    const oldHook = comp.hooks[index];
    const hasChanged = !oldHook || !deps || deps.some((dep, i) => !Object.is(dep, oldHook.deps[i]));

    if (hasChanged) {
      const value = factory();
      comp.hooks[index] = { value, deps };
      return value;
    }
    return oldHook.value;
  }

  function useCallback(callback, deps) {
    return useMemo(() => callback, deps);
  }

  function useRef(initialValue) {
    return useMemo(() => ({ current: initialValue }), []);
  }

  let renderPending = false;
  function scheduleRender() {
    if (renderPending) return;
    renderPending = true;
    requestAnimationFrame(() => {
      renderPending = false;
      if (rootInstance) {
        rootInstance.render();
      }
    });
  }

  global.React = {
    createElement,
    useState,
    useEffect,
    useMemo,
    useCallback,
    useRef,
    _setCurrentComponent: (c) => { currentComponent = c; hookIndex = 0; },
    _scheduleRender: scheduleRender,
    _setRootInstance: (r) => { rootInstance = r; }
  };
})(window);
